<?php

namespace App\Helpers;

/**
 * Temporary fixes to XML generated by Greenter, applied before signing.
 */
class SunatXmlFix
{
    /**
     * Rewrite cbc:TaxAmount with value "0" as "0.00" (format n(12,2)).
     *
     * greenter/xml <= v5.3.0 renders "0" in the EXO (9997), INA (9998) and
     * EXP (9995) TaxSubtotal of invoice, credit note and debit note. Some OSE
     * reject it (error 2048). Fixed upstream in thegreenter/greenter#279;
     * once greenter v5.4 is installed this method has no effect and can be removed.
     *
     * Must run before signing: changing the XML after signing breaks the signature.
     */
    public static function normalizeZeroTaxAmount(string $xml): string
    {
        return preg_replace(
            '/(<cbc:TaxAmount\b[^>]*>)\s*0\s*(<\/cbc:TaxAmount>)/',
            '${1}0.00${2}',
            $xml
        );
    }
}
